from difflib import SequenceMatcher
from datetime import datetime

def detect_duplicate(movement, others):
    def is_date_within_window(date1_str, date2_str, days=1):
        if not date1_str or not date2_str:
            return False
        d1 = datetime.fromisoformat(date1_str)
        d2 = datetime.fromisoformat(date2_str)
        return abs((d1 - d2).days) <= days

    def amounts_equal(abs_amount1, abs_amount2):
        return abs_amount1 == abs_amount2

    def references_equal(ref1, ref2):
        if not ref1 or not ref2:
            return False
        return ref1 == ref2

    def descriptions_similar(desc1, desc2, threshold=0.8):
        if not desc1 or not desc2:
            return False
        return SequenceMatcher(None, desc1, desc2).ratio() >= threshold

    for other in others:
        other_amount = abs(other.get('creditAmount') or other.get('debitAmount', 0))
