from difflib import SequenceMatcher

def trigram_similarity(a: str, b: str) -> float:
    if len(a) == 0 and len(b) == 0:
        return 1.0
    if len(a) == 0 or len(b) == 0:
        return 0.0
    tgram = set()
    for i in range(len(a) - 2):
        tgram.add(a[i:i+3])
    for i in range(len(b) - 2):
        tgram.add(b[i:i+3])
    return 2.0 * len(tgram) / (len(a) + len(b) - 2)

