def generate_summary(movements):
    summary = {
        'totalMovements': len(movements),
        'totalCredits': 0,
        'totalDebits': 0,
        'conciliatedCount': 0,
        'pendingCount': 0,
        'unidentifiedCount': 0,
        'errorCount': 0,
        'duplicateCount': 0,
        'advanceCount': 0,
        'balanceForwardCount': 0,
    }
    for m in movements:
        status = m.get('status', '').lower()
        if status in ('reconciled', 'applied'):
            summary['conciliatedCount'] += 1
        elif status == 'identified':
            summary['pendingCount'] += 1
        elif status in ('pending', 'unidentified'):
            summary['unidentifiedCount'] += 1
        elif status == 'error':
            summary['errorCount'] += 1
        elif status == 'duplicate':
            summary['duplicateCount'] += 1
        else:
            summary['unidentifiedCount'] += 1
        if m.get('creditAmount') is not None and m['creditAmount'] > 0:
            summary['totalCredits'] += m['creditAmount']
        if m.get('debitAmount') is not None and m['debitAmount'] > 0:
            summary['totalDebits'] += m['debitAmount']
    return summary
